import{_ as t,H as e,f as I,i as n}from"./chunks/framework.BH2BK_3i.js";const s=JSON.parse('{"title":"Q69 | AIAgent：AI原生应用和Agent的落地场景","description":"","frontmatter":{},"headers":[],"relativePath":"致程序员：AI百问百答/Q69｜AIAgent：AI原生应用和Agent的落地场景.md","filePath":"致程序员：AI百问百答/Q69｜AIAgent：AI原生应用和Agent的落地场景.md","lastUpdated":1795559851000}'),l={name:"致程序员：AI百问百答/Q69｜AIAgent：AI原生应用和Agent的落地场景.md"};function a(i,A,p,_,g,o){return e(),I("div",null,[...A[0]||(A[0]=[n('<h1 id="q69-aiagent-ai原生应用和agent的落地场景" tabindex="-1">Q69 | AIAgent：AI原生应用和Agent的落地场景 <a class="header-anchor" href="#q69-aiagent-ai原生应用和agent的落地场景" aria-label="Permalink to &quot;Q69 | AIAgent：AI原生应用和Agent的落地场景&quot;">​</a></h1><ul><li>作者介绍：李锟，资深软件架构师，前阿里巴巴高级技术专家</li></ul><p>Q：AI 原生应用和 Agent 有哪些比较好的落地场景？可以给到我们的启发有哪些？</p><p>李锟：我个人觉得，没有必要追求百分之百的 “AI 原生”。因为大多数真实的行业应用都是混合型应用，其中只有一部分功能会用到 AI，有些则只是简单用到了 LLM，并没有研发自己的机器学习算法，当然，还是有研发了自己的机器学习算法、并且训练了自己的特定 AI 模型。根据我的观察，在国内最早应用 AI Agent 的有以下领域：</p><ol><li><p>客服领域：在 LLM 诞生之前，电商、物流等行业的客服系统就已经在应用传统的 NLP 技术实现客服机器人，以达到提高效率、降低成本的目标。LLM 比传统的 NLP 技术强大得多，开发成本也低得多，因此这些系统有非常强的动力很快迁移到基于 LLM 的 AI Agent 应用。</p></li><li><p>在线教育领域：很多在线教育平台都快速拥抱了 LLM 和 AI Agent。原因很容易理解，AIAgent 对于在线教育的业务模式帮助确实非常大，除了可以提高效率、降低成本外，还可以大幅改善用户体验。由 AI Agent 驱动的数字人老师，教学效果在快速提升。</p></li></ol><p>一个非常成功的案例是著名在线教育平台多邻国宣布 All in AI。</p><p>拥抱 AI 就是整个在线教育行业的大趋势，你对 AI 漠视，承担的风险就是会被淘汰出局。</p><ol start="3"><li><p>自媒体 + 直播领域：在自媒体 + 直播领域，同样也落地了很多 AI 应用。AI Agent 在这个领域的主要作用是开发一套工具链来整合各种已有的 AIGC 工具，大幅提高生成内容的效率，降低制作成本。字节跳动、腾讯等大公司都在持续研发基于 AI 的工具链，此外相关的开源社区也极为繁荣。</p></li><li><p>旅游行业：目前已经有一些旅游景区开发了自己的智能导游机器人，这些机器人可以为游客提供与该景区相关的全面服务，包括攻略设计、交通、酒店、门票预订、基于游客位置介绍附近景点相关信息、附近的餐饮、卫生间等等。此外还有个功能叫 “AI 照相馆”，游客在 AI 照相馆上传自己的照片后，可以将模板中模特的形象自动替换为游客形象，生成一张高清照片。总之，使用 AI 应用会大幅改善旅游景区的服务质量，增加旅游景区的趣味性，对于年轻人会很有吸引力。</p></li></ol><p>上述的例子都是 to C 的，其实在 to B 领域也有不少 AI Agent 落地的成功案例，例如在法律行业、投资行业等等，我就不一一列举了。</p><p>从我最近几年对于 AI 行业应用的观察，我有以下几点体会：</p><ol><li>AI Agent 是一场革命，确实没错，不过跟 30 年前开始普及的 Web 类似，最先应用 AIAgent 的并不是一些传统的核心商业领域，更多的是一些边缘领域。最关键的还是找到与已</li></ol><ul><li>有业务模式的最佳契合点，这样 AI Agent 才能扮演重要角色，而不仅仅作为一个“花瓶”角色，随时可能会被废弃。</li></ul><ol start="2"><li><p>AI 技术非常复杂，技术栈也非常深。AI 技术要真正普及，必须实现清晰的分层和分工协作。各个层的开发者各司其职、通力协作，才能开发出理想的 AI Agent。LLM 的诞生和飞速发展，实现了 AI 技术的分层和分工协作，极大降低了 AI 应用开发的门槛。如今普通的开发者只要有兴趣，都可以来开发基于 LLM 的 AI Agent，这在 5 年前的传统 NLP 技术时代是无法想象的。</p></li><li><p>AI 技术确实很好玩，但是我们如果只是抱着“玩技术”的心态来学习 AI 技术，很容易事倍功半。作为开发者，还是应该深入思考一些 AI 技术最佳的落地场景，尽力去开发一些非常有趣、也非常有用的 AI 应用，让非技术背景的普通用户真正受益。这样的应用才是有商业前景的应用，可以形成良性循环并且可持续发展。在应用的发展过程中，很多最新、最棒的AI 技术才能发挥出最佳的效用。</p></li></ol>',13)])])}const L=t(l,[["render",a]]);export{s as __pageData,L as default};
